 46	        #[doc = "Unsigned integer with "]
 47	        #[doc = stringify!($bits)]
 48	        #[doc = "bits size."]
 49	        pub type $num = $crate::arithmetic::uint::Uint<
 50	            { usize::div_ceil($bits, $crate::arithmetic::Limb::BITS as usize) },
 51	        >;
 52	    };
 53	}
