 87	    /// Returns true if this number is odd (constant).
 88	    #[doc(hidden)]
 89	    #[inline]
 90	    #[must_use]
 91	    pub const fn is_odd(&self) -> bool {
 92	        self.limbs[0] & 1 == 1
