103	    /// Checks `self` is greater or equal then `rhs` (constant).
104	    #[must_use]
105	    #[inline(always)]
106	    pub const fn ge(&self, rhs: &Self) -> bool {
107	        let mut result = true;
108	        const_for_unroll6!((i in 0..N) {
109	            let a = self.limbs[i];
110	            let b = rhs.limbs[i];
111	            if a > b {
112	                result = true;
113	            } else if a < b {
114	                result = false;
115	            }
116	        });
117	        result
118	    }
