120	    /// Checks `self` is greater then `rhs` (constant).
121	    #[must_use]
122	    #[inline(always)]
123	    pub const fn gt(&self, rhs: &Self) -> bool {
124	        let mut result = false;
125	        const_for_unroll6!((i in 0..N) {
126	            let a = self.limbs[i];
127	            let b = rhs.limbs[i];
128	            if a > b {
129	                result = true;
130	            } else if a < b {
