178	    /// Checks if `self` is equal to `rhs` (constant).
179	    #[must_use]
180	    #[inline(always)]
181	    pub const fn eq(&self, rhs: &Self) -> bool {
182	        const_for!((i in 0..N) {
183	            if self.limbs[i] != rhs.limbs[i] {
184	                return false;
185	            }
186	        });
187	        true
188	    }
