243	    /// Multiplies `self` by `2` in-place, returning whether overflow occurred.
244	    #[inline(always)]
245	    #[allow(unused)]
246	    pub fn checked_mul2_assign(&mut self) -> bool {
247	        let mut last = 0;
248	        const_for_unroll6!((i in 0..N) {
249	            let a = &mut self.limbs[i];
250	            let tmp = *a >> 63;
251	            *a <<= 1;
252	            *a |= last;
253	            last = tmp;
254	        });
255	        last != 0
256	    }
