258	    /// Multiplies `self` by `2`, returning the result and whether overflow
259	    /// occurred (constant).
260	    const fn checked_mul2(mut self) -> (Self, bool) {

260	    const fn checked_mul2(mut self) -> (Self, bool) {
261	        let mut last = 0;
262	        const_for!((i in 0..N) {
263	            let a = self.limbs[i];
264	            let tmp = a >> 63;
265	            self.limbs[i] <<= 1;
266	            self.limbs[i] |= last;
267	            last = tmp;
268	        });
269	        (self, last != 0)
270	    }
