272	    /// Divide `self` by `2` in-place.
273	    pub fn div2_assign(&mut self) {
274	        let mut t = 0;
275	        for a in self.limbs.iter_mut().rev() {
276	            let t2 = *a << 63;
277	            *a >>= 1;
278	            *a |= t;
279	            t = t2;
280	        }
281	    }
